-- Add structured installation details for data-driven server pages.
ALTER TABLE servers ADD COLUMN details_json TEXT NOT NULL DEFAULT '{}';
UPDATE servers SET details_json='{"summary":"Maintainer-documented hosted GitHub MCP endpoint.","documentationUrl":"https://github.com/github/github-mcp-server/blob/main/README.md","security":["Grant only required GitHub permissions.","Review tool approvals before repository changes."],"installations":[{"title":"Hosted HTTP","client":"VS Code","os":"Any","config":{"servers":{"github":{"type":"http","url":"https://api.githubcopilot.com/mcp/"}}},"notes":"Authenticate using the supported OAuth flow."}]}' WHERE id='github-mcp';
UPDATE servers SET details_json='{"summary":"Filesystem access is limited to explicitly permitted directories.","documentationUrl":"https://github.com/modelcontextprotocol/servers/blob/main/src/filesystem/README.md","security":["Restrict access to the narrowest possible directory."],"installations":[{"title":"Local NPX","client":"Claude Desktop","os":"macOS / Linux","config":{"mcpServers":{"filesystem":{"command":"npx","args":["-y","@modelcontextprotocol/server-filesystem","/ABSOLUTE/PATH/TO/ALLOWED/DIRECTORY"]}}},"notes":"Replace the placeholder with an absolute path."}]}' WHERE id='filesystem-mcp';
UPDATE servers SET details_json='{"summary":"Local NPX server for sequential thinking.","documentationUrl":"https://github.com/modelcontextprotocol/servers/blob/main/src/sequentialthinking/README.md","installations":[{"title":"Local NPX","client":"Claude Desktop","os":"macOS / Linux","config":{"mcpServers":{"sequential-thinking":{"command":"npx","args":["-y","@modelcontextprotocol/server-sequential-thinking"]}}},"notes":"Check the maintainer''s Node.js version requirements."}]}' WHERE id='sequential-thinking-mcp';
